extends RefCounted

const DIRS: Array[Vector2i] = [Vector2i(0, -1), Vector2i(1, 0), Vector2i(0, 1), Vector2i(-1, 0)]


func neighbors(pos: Vector2i, width: int, height: int) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	for d in DIRS:
		var p := pos + d
		if p.x >= 0 and p.y >= 0 and p.x < width and p.y < height:
			result.append(p)
	return result


func shortest_path_length(rows: Array, start: Vector2i, goal: Vector2i) -> int:
	var height := rows.size()
	if height == 0:
		return -1
	var width: int = (rows[0] as String).length()
	if _blocked(rows, start) or _blocked(rows, goal):
		return -1
	var dist := {start: 0}
	var queue: Array[Vector2i] = [start]
	var head := 0
	while head < queue.size():
		var cur := queue[head]
		head += 1
		if cur == goal:
			return dist[cur]
		for n in neighbors(cur, width, height):
			if not dist.has(n) and not _blocked(rows, n):
				dist[n] = dist[cur] + 1
				queue.append(n)
	return -1


func _blocked(rows: Array, p: Vector2i) -> bool:
	return (rows[p.y] as String)[p.x] == "#"

extends RefCounted


func hit_damage(base: int, armor: int, crit: bool) -> int:
	var raw := base * 2 if crit else base
	return maxi(1, raw - armor)


func hp_after_hits(hp: int, armor: int, hits: Array) -> Array:
	var result: Array = []
	var current := hp
	for hit in hits:
		if current > 0:
			current = maxi(0, current - hit_damage(hit[0], armor, hit[1]))
		result.append(current)
	return result


func cooldown_left_ms(last_used_ms: int, cooldown_ms: int, now_ms: int) -> int:
	if last_used_ms < 0:
		return 0
	return maxi(0, last_used_ms + cooldown_ms - now_ms)

extends RefCounted


@warning_ignore("integer_division")
func format_duration(seconds: int) -> String:
	if seconds < 0:
		return "-" + format_duration(-seconds)
	var h := seconds / 3600
	var m := (seconds % 3600) / 60
	var s := seconds % 60
	if h > 0:
		return "%d:%02d:%02d" % [h, m, s]
	return "%d:%02d" % [m, s]


func parse_duration(text: String) -> int:
	var parts := text.split(":")
	if parts.size() > 3:
		return -1
	for p in parts:
		if p.is_empty():
			return -1
		for ch in p:
			if not ch in "0123456789":
				return -1
	var total := 0
	for i in parts.size():
		var v := parts[i].to_int()
		if i > 0 and v >= 60:
			return -1
		total = total * 60 + v
	return total

using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class PlayerMovement : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 6f;
    [SerializeField] private float jumpHeight = 1.5f;
    [SerializeField] private Transform groundCheck;
    [SerializeField] private float groundRadius = 0.25f;
    [SerializeField] private LayerMask groundMask;
    [SerializeField] private Transform cameraTransform;

    private Rigidbody rb;
    private Vector3 moveDirection;
    private bool jumpRequested;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        rb.freezeRotation = true;
        if (cameraTransform == null && Camera.main != null)
        {
            cameraTransform = Camera.main.transform;
        }
    }

    private void Update()
    {
        Vector2 input = Vector2.ClampMagnitude(new Vector2(Input.GetAxisRaw("Horizontal"), Input.GetAxisRaw("Vertical")), 1f);
        Vector3 forward = Vector3.forward;
        Vector3 right = Vector3.right;
        if (cameraTransform != null)
        {
            forward = Vector3.ProjectOnPlane(cameraTransform.forward, Vector3.up).normalized;
            right = Vector3.ProjectOnPlane(cameraTransform.right, Vector3.up).normalized;
        }
        moveDirection = forward * input.y + right * input.x;
        if (Input.GetButtonDown("Jump"))
        {
            jumpRequested = true;
        }
    }

    private void FixedUpdate()
    {
        bool grounded = Physics.CheckSphere(groundCheck.position, groundRadius, groundMask, QueryTriggerInteraction.Ignore);
        Vector3 velocity = rb.linearVelocity;
        velocity.x = moveDirection.x * moveSpeed;
        velocity.z = moveDirection.z * moveSpeed;
        if (jumpRequested && grounded)
        {
            velocity.y = Mathf.Sqrt(2f * -Physics.gravity.y * jumpHeight);
        }
        jumpRequested = false;
        rb.linearVelocity = velocity;
    }
}

using UnityEngine;
using UnityEngine.Events;

public class Health : MonoBehaviour
{
    [SerializeField, Min(1)] private int maxHealth = 100;
    [SerializeField, Min(0f)] private float invulnerabilitySeconds = 0.5f;

    public UnityEvent<int, int> onHealthChanged = new UnityEvent<int, int>();
    public UnityEvent onDied = new UnityEvent();

    public int Current { get; private set; }
    public int Max => maxHealth;
    public bool IsDead { get; private set; }

    private float invulnerableUntil = float.NegativeInfinity;

    private void Awake()
    {
        Current = maxHealth;
    }

    public bool TakeDamage(int amount)
    {
        if (amount <= 0 || IsDead || Time.time < invulnerableUntil)
        {
            return false;
        }
        Current = Mathf.Max(0, Current - amount);
        invulnerableUntil = Time.time + invulnerabilitySeconds;
        onHealthChanged.Invoke(Current, maxHealth);
        if (Current == 0)
        {
            IsDead = true;
            onDied.Invoke();
        }
        return true;
    }

    public void Heal(int amount)
    {
        if (amount <= 0 || IsDead)
        {
            return;
        }
        int before = Current;
        Current = Mathf.Min(maxHealth, Current + amount);
        if (Current != before)
        {
            onHealthChanged.Invoke(Current, maxHealth);
        }
    }
}

using UnityEngine;
using UnityEngine.Pool;

[RequireComponent(typeof(Rigidbody))]
public class Projectile : MonoBehaviour
{
    [SerializeField] private float lifetime = 3f;

    private Rigidbody rb;
    private IObjectPool<Projectile> pool;
    private float despawnAt;
    private bool released;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
    }

    public void Init(IObjectPool<Projectile> owner)
    {
        pool = owner;
    }

    public void Launch(Vector3 position, Quaternion rotation, float speed)
    {
        transform.SetPositionAndRotation(position, rotation);
        rb.position = position;
        rb.rotation = rotation;
        rb.angularVelocity = Vector3.zero;
        rb.linearVelocity = rotation * Vector3.forward * speed;
        despawnAt = Time.time + lifetime;
        released = false;
    }

    private void Update()
    {
        if (Time.time >= despawnAt)
        {
            ReturnToPool();
        }
    }

    private void OnCollisionEnter(Collision collision)
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (released)
        {
            return;
        }
        released = true;
        pool.Release(this);
    }
}

public class ProjectileSpawner : MonoBehaviour
{
    [SerializeField] private Projectile prefab;
    [SerializeField] private Transform muzzle;
    [SerializeField] private float shotsPerSecond = 8f;
    [SerializeField] private float speed = 30f;
    [SerializeField] private int defaultCapacity = 20;
    [SerializeField] private int maxSize = 100;

    private ObjectPool<Projectile> pool;
    private float nextShotTime;

    private void Awake()
    {
        pool = new ObjectPool<Projectile>(
            createFunc: CreateProjectile,
            actionOnGet: p => p.gameObject.SetActive(true),
            actionOnRelease: p => p.gameObject.SetActive(false),
            actionOnDestroy: p => Destroy(p.gameObject),
            collectionCheck: true,
            defaultCapacity: defaultCapacity,
            maxSize: maxSize);
    }

    private Projectile CreateProjectile()
    {
        Projectile p = Instantiate(prefab);
        p.Init(pool);
        p.gameObject.SetActive(false);
        return p;
    }

    private void Update()
    {
        if (Input.GetButton("Fire1") && Time.time >= nextShotTime)
        {
            nextShotTime = Time.time + 1f / shotsPerSecond;
            Projectile p = pool.Get();
            p.Launch(muzzle.position, muzzle.rotation, speed);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

[Serializable]
public class PlayerData
{
    public int level = 1;
    public Vector3 position;
    public List<string> inventory = new List<string>();
}

public static class SaveSystem
{
    private static string SavePath => Path.Combine(Application.persistentDataPath, "save.json");

    public static void Save(PlayerData data)
    {
        string json = JsonUtility.ToJson(data, true);
        string tempPath = SavePath + ".tmp";
        File.WriteAllText(tempPath, json);
        if (File.Exists(SavePath))
        {
            File.Replace(tempPath, SavePath, null);
        }
        else
        {
            File.Move(tempPath, SavePath);
        }
    }

    public static PlayerData Load()
    {
        if (!File.Exists(SavePath))
        {
            return new PlayerData();
        }
        try
        {
            PlayerData data = JsonUtility.FromJson<PlayerData>(File.ReadAllText(SavePath));
            return data ?? new PlayerData();
        }
        catch (Exception e) when (e is IOException || e is ArgumentException)
        {
            Debug.LogWarning($"Save file unreadable, using defaults: {e.Message}");
            return new PlayerData();
        }
    }
}

using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class EnemyPatrol : MonoBehaviour
{
    [SerializeField] private Transform[] waypoints;
    [SerializeField] private float detectionRadius = 10f;
    [SerializeField] private float loseTargetAfter = 3f;
    [SerializeField] private LayerMask sightBlockers;
    [SerializeField] private float patrolSpeed = 2f;
    [SerializeField] private float chaseSpeed = 4.5f;

    private NavMeshAgent agent;
    private Transform player;
    private int waypointIndex;
    private float lastSeenTime = float.NegativeInfinity;
    private bool chasing;

    private void Awake()
    {
        agent = GetComponent<NavMeshAgent>();
    }

    private void Start()
    {
        GameObject found = GameObject.FindWithTag("Player");
        if (found != null)
        {
            player = found.transform;
        }
        agent.speed = patrolSpeed;
        GoToNextWaypoint();
    }

    private void Update()
    {
        if (CanSeePlayer())
        {
            lastSeenTime = Time.time;
            if (!chasing)
            {
                chasing = true;
                agent.speed = chaseSpeed;
            }
        }

        if (chasing)
        {
            if (Time.time - lastSeenTime > loseTargetAfter)
            {
                chasing = false;
                agent.speed = patrolSpeed;
                GoToNextWaypoint();
            }
            else
            {
                agent.SetDestination(player.position);
            }
            return;
        }

        if (!agent.pathPending && agent.remainingDistance <= agent.stoppingDistance + 0.1f)
        {
            GoToNextWaypoint();
        }
    }

    private bool CanSeePlayer()
    {
        if (player == null)
        {
            return false;
        }
        Vector3 eye = transform.position + Vector3.up * 1.5f;
        Vector3 toPlayer = player.position + Vector3.up - eye;
        float distance = toPlayer.magnitude;
        if (distance > detectionRadius)
        {
            return false;
        }
        if (distance < 0.01f)
        {
            return true;
        }
        return !Physics.Raycast(eye, toPlayer / distance, distance, sightBlockers, QueryTriggerInteraction.Ignore);
    }

    private void GoToNextWaypoint()
    {
        if (waypoints == null || waypoints.Length == 0)
        {
            return;
        }
        agent.SetDestination(waypoints[waypointIndex].position);
        waypointIndex = (waypointIndex + 1) % waypoints.Length;
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, detectionRadius);
    }
}

