[CreateAssetMenu(fileName = "NewItem", menuName = "Inventory/Item Definition")]
public class ItemDefinition : ScriptableObject
{
    public string id;
    public string displayName;
    public Sprite icon;
    [Min(1)] public int maxStack = 1;
}

[Serializable]
public class ItemStack
{
    public ItemDefinition item;
    public int count;

    public bool IsEmpty => item == null || count <= 0;
}

public class Inventory : MonoBehaviour
{
    [SerializeField, Min(1)] private int slotCount = 20;
    [SerializeField] private List<ItemStack> slots = new List<ItemStack>();

    public event Action OnChanged;

    public IReadOnlyList<ItemStack> Slots => slots;

    private void Awake()
    {
        while (slots.Count < slotCount)
        {
            slots.Add(new ItemStack());
        }
    }

    /// <summary>Adds up to amount items and returns how many did not fit.</summary>
    public int TryAdd(ItemDefinition item, int amount)
    {
        if (item == null || amount <= 0)
        {
            return amount;
        }
        int remaining = amount;
        foreach (ItemStack stack in slots)
        {
            if (remaining == 0) break;
            if (stack.item == item && stack.count < item.maxStack)
            {
                int add = Mathf.Min(item.maxStack - stack.count, remaining);
                stack.count += add;
                remaining -= add;
            }
        }
        foreach (ItemStack stack in slots)
        {
            if (remaining == 0) break;
            if (stack.IsEmpty)
            {
                int add = Mathf.Min(item.maxStack, remaining);
                stack.item = item;
                stack.count = add;
                remaining -= add;
            }
        }
        if (remaining != amount)
        {
            OnChanged?.Invoke();
        }
        return remaining;
    }

    public int Count(ItemDefinition item)
    {
        int total = 0;
        foreach (ItemStack stack in slots)
        {
            if (stack.item == item) total += stack.count;
        }
        return total;
    }

    public bool Remove(ItemDefinition item, int amount)
    {
        if (item == null || amount <= 0 || Count(item) < amount)
        {
            return false;
        }
        for (int i = slots.Count - 1; i >= 0 && amount > 0; i--)
        {
            ItemStack stack = slots[i];
            if (stack.item != item) continue;
            int take = Mathf.Min(stack.count, amount);
            stack.count -= take;
            amount -= take;
            if (stack.count == 0) stack.item = null;
        }
        OnChanged?.Invoke();
        return true;
    }
}

extends CharacterBody2D

@export var speed: float = 220.0
@export var acceleration: float = 1600.0
@export var jump_velocity: float = -420.0
@export var coyote_time: float = 0.1
@export var jump_buffer_time: float = 0.12

var gravity: float = ProjectSettings.get_setting("physics/2d/default_gravity")
var _coyote_timer: float = 0.0
var _jump_buffer_timer: float = 0.0


func _physics_process(delta: float) -> void:
	if is_on_floor():
		_coyote_timer = coyote_time
	else:
		_coyote_timer -= delta
		velocity.y += gravity * delta

	if Input.is_action_just_pressed("jump"):
		_jump_buffer_timer = jump_buffer_time
	else:
		_jump_buffer_timer -= delta

	if _jump_buffer_timer > 0.0 and _coyote_timer > 0.0:
		velocity.y = jump_velocity
		_jump_buffer_timer = 0.0
		_coyote_timer = 0.0

	if Input.is_action_just_released("jump") and velocity.y < 0.0:
		velocity.y *= 0.5

	var direction := Input.get_axis("move_left", "move_right")
	velocity.x = move_toward(velocity.x, direction * speed, acceleration * delta)
	move_and_slide()

extends Node2D

signal wave_started(wave: int)
signal wave_cleared(wave: int)

@export var enemy_scene: PackedScene
@export var spawn_points: Array[Marker2D] = []
@export var base_count: int = 3
@export var extra_per_wave: int = 2
@export var spawn_interval: float = 0.5
@export var time_between_waves: float = 3.0

@onready var _spawn_timer: Timer = $SpawnTimer

var wave: int = 0
var _to_spawn: int = 0
var _alive: int = 0


func _ready() -> void:
	_spawn_timer.wait_time = spawn_interval
	_spawn_timer.one_shot = false
	_spawn_timer.timeout.connect(_on_spawn_timer_timeout)
	_start_next_wave()


func _start_next_wave() -> void:
	wave += 1
	_to_spawn = base_count + extra_per_wave * (wave - 1)
	wave_started.emit(wave)
	_spawn_timer.start()


func _on_spawn_timer_timeout() -> void:
	if _to_spawn <= 0 or spawn_points.is_empty() or enemy_scene == null:
		_spawn_timer.stop()
		return
	var enemy := enemy_scene.instantiate() as Node2D
	var point: Marker2D = spawn_points.pick_random()
	_alive += 1
	_to_spawn -= 1
	enemy.tree_exited.connect(_on_enemy_removed)
	add_child(enemy)
	enemy.global_position = point.global_position
	if _to_spawn == 0:
		_spawn_timer.stop()


func _on_enemy_removed() -> void:
	_alive -= 1
	if not is_inside_tree():
		return
	if _alive == 0 and _to_spawn == 0:
		wave_cleared.emit(wave)
		await get_tree().create_timer(time_between_waves).timeout
		_start_next_wave()

extends Node
## Autoload "Settings": persists audio and video options in user://settings.cfg.

const SETTINGS_PATH := "user://settings.cfg"

var master_volume: float = 1.0
var fullscreen: bool = false


func _ready() -> void:
	load_settings()


func set_master_volume(linear: float) -> void:
	master_volume = clampf(linear, 0.0, 1.0)
	var bus := AudioServer.get_bus_index("Master")
	AudioServer.set_bus_volume_db(bus, linear_to_db(master_volume))
	AudioServer.set_bus_mute(bus, master_volume <= 0.0)


func set_fullscreen(enabled: bool) -> void:
	fullscreen = enabled
	var mode := DisplayServer.WINDOW_MODE_FULLSCREEN if enabled else DisplayServer.WINDOW_MODE_WINDOWED
	DisplayServer.window_set_mode(mode)


func save_settings() -> void:
	var config := ConfigFile.new()
	config.set_value("audio", "master_volume", master_volume)
	config.set_value("video", "fullscreen", fullscreen)
	var err := config.save(SETTINGS_PATH)
	if err != OK:
		push_error("Could not save settings: %s" % error_string(err))


func load_settings() -> void:
	var config := ConfigFile.new()
	var err := config.load(SETTINGS_PATH)
	if err != OK and err != ERR_FILE_NOT_FOUND:
		push_warning("Settings file unreadable (%s), using defaults" % error_string(err))
	set_master_volume(float(config.get_value("audio", "master_volume", 1.0)))
	set_fullscreen(bool(config.get_value("video", "fullscreen", false)))

