void AHeroCharacter::NotifyControllerChanged()
{
	Super::NotifyControllerChanged();
	if (APlayerController* PC = Cast<APlayerController>(Controller))
	{
		if (UEnhancedInputLocalPlayerSubsystem* Subsystem =
				ULocalPlayer::GetSubsystem<UEnhancedInputLocalPlayerSubsystem>(PC->GetLocalPlayer()))
		{
			Subsystem->AddMappingContext(DefaultMappingContext, 0);
		}
	}
}

void AHeroCharacter::SetupPlayerInputComponent(UInputComponent* PlayerInputComponent)
{
	Super::SetupPlayerInputComponent(PlayerInputComponent);
	if (UEnhancedInputComponent* Input = Cast<UEnhancedInputComponent>(PlayerInputComponent))
	{
		Input->BindAction(JumpAction, ETriggerEvent::Started, this, &ACharacter::Jump);
		Input->BindAction(JumpAction, ETriggerEvent::Completed, this, &ACharacter::StopJumping);
		Input->BindAction(MoveAction, ETriggerEvent::Triggered, this, &AHeroCharacter::Move);
		Input->BindAction(LookAction, ETriggerEvent::Triggered, this, &AHeroCharacter::Look);
	}
}

void AHeroCharacter::Move(const FInputActionValue& Value)
{
	const FVector2D Axis = Value.Get<FVector2D>();
	if (Controller == nullptr)
	{
		return;
	}
	const FRotator YawRotation(0.f, Controller->GetControlRotation().Yaw, 0.f);
	const FVector Forward = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);
	const FVector Right = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);
	AddMovementInput(Forward, Axis.Y);
	AddMovementInput(Right, Axis.X);
}

void AHeroCharacter::Look(const FInputActionValue& Value)
{
	const FVector2D Axis = Value.Get<FVector2D>();
	AddControllerYawInput(Axis.X);
	AddControllerPitchInput(Axis.Y);
}

extends RefCounted


func wrap_tile(pos: Vector2i, size: Vector2i) -> Vector2i:
	return Vector2i(posmod(pos.x, size.x), posmod(pos.y, size.y))


func chunk_of(pos: Vector2i, chunk_size: int) -> Vector2i:
	return Vector2i(floori(float(pos.x) / chunk_size), floori(float(pos.y) / chunk_size))


func local_in_chunk(pos: Vector2i, chunk_size: int) -> Vector2i:
	return Vector2i(posmod(pos.x, chunk_size), posmod(pos.y, chunk_size))


func tiles_in_radius(center: Vector2i, r: int) -> Array[Vector2i]:
	var result: Array[Vector2i] = []
	for dy in range(-r, r + 1):
		var span := r - absi(dy)
		for dx in range(-span, span + 1):
			result.append(center + Vector2i(dx, dy))
	return result

extends RefCounted


func rank_lines(entries: Array) -> PackedStringArray:
	var rows := entries.duplicate()
	rows.sort_custom(_before)
	var lines := PackedStringArray()
	var rank := 0
	for i in rows.size():
		var e: Dictionary = rows[i]
		if i == 0 or e["score"] != rows[i - 1]["score"] or e["time"] != rows[i - 1]["time"]:
			rank = i + 1
		lines.append("%d. %s %s %.2f" % [rank, String(e["name"]).rpad(10, "."), str(e["score"]).pad_zeros(6), e["time"]])
	return lines


func _before(a: Dictionary, b: Dictionary) -> bool:
	if a["score"] != b["score"]:
		return a["score"] > b["score"]
	if a["time"] != b["time"]:
		return a["time"] < b["time"]
	return a["name"] < b["name"]


func count_below(sorted_scores: Array, value: int) -> int:
	return sorted_scores.bsearch(value, true)


func count_at_most(sorted_scores: Array, value: int) -> int:
	return sorted_scores.bsearch(value, false)

extends RefCounted


func parse_command(line: String) -> Dictionary:
	var text := line.strip_edges()
	if not text.begins_with("/"):
		return {}
	var name := text.substr(1).get_slice(" ", 0)
	if name.is_empty():
		return {}
	for ch in name:
		if not ((ch >= "a" and ch <= "z") or (ch >= "A" and ch <= "Z")):
			return {}
	var parts := text.substr(1).split(" ", false)
	var args := parts.slice(1)
	return {"cmd": parts[0].to_lower(), "args": args}


func parse_amount(text: String, default_value: int) -> int:
	if not text.is_valid_int():
		return default_value
	var n := text.to_int()
	if n < 1 or n > 999:
		return default_value
	return n


func give_summary(line: String) -> String:
	var c := parse_command(line)
	if c.is_empty() or c["cmd"] != "give":
		return "unknown command"
	var args: PackedStringArray = c["args"]
	if args.size() < 1 or args.size() > 2:
		return "usage: /give <item> [amount]"
	var amount := 1
	if args.size() == 2:
		amount = parse_amount(args[1], -1)
		if amount == -1:
			return "bad amount: " + args[1]
	return "gave %d x %s" % [amount, args[0]]

extends Node

signal used(charges_left: int)
signal recharged(charges: int)

@export var max_charges: int = 2
@export var recharge_time: float = 1.0

var charges: int = 0

var _timer: Timer


func _ready() -> void:
	charges = max_charges
	_timer = Timer.new()
	_timer.name = "RechargeTimer"
	_timer.one_shot = true
	_timer.wait_time = recharge_time
	_timer.timeout.connect(_on_recharge_timeout)
	add_child(_timer)


func try_use() -> bool:
	if charges <= 0:
		return false
	charges -= 1
	used.emit(charges)
	if _timer.is_stopped():
		_timer.start(recharge_time)
	return true


func time_until_next_charge() -> float:
	if charges >= max_charges:
		return 0.0
	return _timer.time_left


func _on_recharge_timeout() -> void:
	charges = mini(charges + 1, max_charges)
	recharged.emit(charges)
	if charges < max_charges:
		_timer.start(recharge_time)

extends Node

signal item_changed(item_id: String, new_count: int)
signal loaded(item_count: int)

@export var max_stack: int = 99

var _items: Dictionary = {}


func add_item(item_id: String, amount: int) -> int:
	if amount <= 0:
		return 0
	var have: int = _items.get(item_id, 0)
	var added := mini(amount, max_stack - have)
	if added <= 0:
		return 0
	_items[item_id] = have + added
	item_changed.emit(item_id, have + added)
	return added


func remove_item(item_id: String, amount: int) -> bool:
	var have: int = _items.get(item_id, 0)
	if amount <= 0 or have < amount:
		return false
	var left := have - amount
	if left == 0:
		_items.erase(item_id)
	else:
		_items[item_id] = left
	item_changed.emit(item_id, left)
	return true


func get_count(item_id: String) -> int:
	return _items.get(item_id, 0)


func get_items() -> PackedStringArray:
	var ids := PackedStringArray(_items.keys())
	ids.sort()
	return ids


func save_to(path: String) -> Error:
	var cfg := ConfigFile.new()
	for id in _items:
		cfg.set_value("inventory", id, _items[id])
	return cfg.save(path)


func load_from(path: String) -> Error:
	var cfg := ConfigFile.new()
	var err := cfg.load(path)
	if err != OK:
		return err
	_items.clear()
	if cfg.has_section("inventory"):
		for id in cfg.get_section_keys("inventory"):
			var count := int(cfg.get_value("inventory", id, 0))
			if count > 0:
				_items[id] = mini(count, max_stack)
	loaded.emit(_items.size())
	return OK

extends Node2D

enum State { IDLE, CHASE, ATTACK, DEAD }

signal state_changed(old_state: State, new_state: State)

@export var chase_range: float = 200.0
@export var attack_range: float = 40.0

var state: State = State.IDLE


func _ready() -> void:
	add_to_group("enemies")


func update_ai(distance_to_player: float) -> void:
	if state == State.DEAD:
		return
	if distance_to_player <= attack_range:
		_set_state(State.ATTACK)
	elif distance_to_player <= chase_range:
		_set_state(State.CHASE)
	else:
		_set_state(State.IDLE)


func die() -> void:
	if state == State.DEAD:
		return
	remove_from_group("enemies")
	_set_state(State.DEAD)


static func alert_all(tree: SceneTree, distance: float) -> void:
	tree.call_group("enemies", "update_ai", distance)


func knockback(direction: Vector2, distance: float, duration: float) -> Tween:
	var tween := create_tween()
	tween.tween_property(self, "position", position + direction.normalized() * distance, duration)
	return tween


func _set_state(new_state: State) -> void:
	if new_state == state:
		return
	var old := state
	state = new_state
	state_changed.emit(old, new_state)

using System;
using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class DashAbility : MonoBehaviour
{
    [SerializeField] private float dashSpeed = 18f;
    [SerializeField] private float dashDuration = 0.2f;
    [SerializeField] private float cooldown = 1f;

    private Rigidbody rb;
    private float cooldownEndTime;

    public bool IsDashing { get; private set; }

    public float CooldownRemaining => Mathf.Max(0f, cooldownEndTime - Time.time);

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
    }

    public bool TryDash(Vector3 direction)
    {
        direction.y = 0f;
        if (IsDashing || CooldownRemaining > 0f || direction.sqrMagnitude < 0.0001f)
        {
            return false;
        }
        _ = DashAsync(direction.normalized);
        return true;
    }

    private async Awaitable DashAsync(Vector3 direction)
    {
        IsDashing = true;
        cooldownEndTime = Time.time + dashDuration + cooldown;
        float previousDamping = rb.linearDamping;
        bool previousGravity = rb.useGravity;
        Vector3 previousVelocity = rb.linearVelocity;
        try
        {
            rb.linearDamping = 0f;
            rb.useGravity = false;
            rb.linearVelocity = direction * dashSpeed;
            await Awaitable.WaitForSecondsAsync(dashDuration, destroyCancellationToken);
            await Awaitable.FixedUpdateAsync(destroyCancellationToken);
            rb.linearVelocity = new Vector3(previousVelocity.x, 0f, previousVelocity.z);
        }
        catch (OperationCanceledException)
        {
            return;
        }
        finally
        {
            if (rb != null)
            {
                rb.linearDamping = previousDamping;
                rb.useGravity = previousGravity;
            }
            IsDashing = false;
        }
    }
}

