[RequireComponent(typeof(CharacterController))]
public class TopDownShooterInput : MonoBehaviour
{
    [SerializeField] private InputActionReference moveAction;
    [SerializeField] private InputActionReference aimAction;
    [SerializeField] private InputActionReference fireAction;
    [SerializeField] private float moveSpeed = 6f;
    [SerializeField] private Camera viewCamera;

    private CharacterController controller;
    private float verticalSpeed;

    private void Awake()
    {
        controller = GetComponent<CharacterController>();
        if (viewCamera == null)
        {
            viewCamera = Camera.main;
        }
    }

    private void OnEnable()
    {
        moveAction.action.Enable();
        aimAction.action.Enable();
        fireAction.action.Enable();
        fireAction.action.performed += OnFirePerformed;
    }

    private void OnDisable()
    {
        fireAction.action.performed -= OnFirePerformed;
        moveAction.action.Disable();
        aimAction.action.Disable();
        fireAction.action.Disable();
    }

    private void Update()
    {
        Vector2 input = Vector2.ClampMagnitude(moveAction.action.ReadValue<Vector2>(), 1f);
        Vector3 velocity = new Vector3(input.x, 0f, input.y) * moveSpeed;

        verticalSpeed = controller.isGrounded ? -1f : verticalSpeed + Physics.gravity.y * Time.deltaTime;
        velocity.y = verticalSpeed;
        controller.Move(velocity * Time.deltaTime);

        AimAtPointer();
    }

    private void AimAtPointer()
    {
        if (viewCamera == null)
        {
            return;
        }
        Vector2 screenPos = aimAction.action.ReadValue<Vector2>();
        Ray ray = viewCamera.ScreenPointToRay(screenPos);
        Plane ground = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        if (ground.Raycast(ray, out float enter))
        {
            Vector3 look = ray.GetPoint(enter) - transform.position;
            look.y = 0f;
            if (look.sqrMagnitude > 0.0001f)
            {
                transform.rotation = Quaternion.LookRotation(look, Vector3.up);
            }
        }
    }

    private void OnFirePerformed(InputAction.CallbackContext context)
    {
        Fire();
    }

    private void Fire()
    {
        Debug.Log($"Fire towards {transform.forward}");
    }
}

using System.Collections.Generic;
using UnityEngine;

public interface IDamageable
{
    void TakeDamage(float amount);
}

public class Explosion : MonoBehaviour
{
    [SerializeField] private float radius = 6f;
    [SerializeField] private float maxDamage = 80f;
    [SerializeField] private float force = 900f;
    [SerializeField] private float upwardsModifier = 0.5f;
    [SerializeField] private LayerMask damageMask = ~0;
    [SerializeField] private LayerMask obstacleMask;

    private readonly Collider[] hits = new Collider[64];
    private readonly HashSet<Rigidbody> pushed = new HashSet<Rigidbody>();
    private readonly HashSet<IDamageable> damaged = new HashSet<IDamageable>();

    public void Explode()
    {
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, radius, hits, damageMask, QueryTriggerInteraction.Ignore);
        pushed.Clear();
        damaged.Clear();

        for (int i = 0; i < count; i++)
        {
            Collider col = hits[i];
            Vector3 target = col.bounds.center;
            if (Physics.Linecast(center, target, obstacleMask, QueryTriggerInteraction.Ignore))
            {
                continue;
            }

            Rigidbody body = col.attachedRigidbody;
            if (body != null && pushed.Add(body))
            {
                body.AddExplosionForce(force, center, radius, upwardsModifier, ForceMode.Impulse);
            }

            IDamageable damageable = col.GetComponentInParent<IDamageable>();
            if (damageable != null && damaged.Add(damageable))
            {
                float distance = Vector3.Distance(center, col.ClosestPoint(center));
                float damage = maxDamage * Mathf.Clamp01(1f - distance / radius);
                if (damage > 0f)
                {
                    damageable.TakeDamage(damage);
                }
            }
            hits[i] = null;
        }
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = new Color(1f, 0.4f, 0f, 0.4f);
        Gizmos.DrawWireSphere(transform.position, radius);
    }
}

