#include "HitscanWeaponComponent.h"
#include "CollisionQueryParams.h"
#include "Engine/World.h"
#include "GameFramework/Actor.h"
#include "GameFramework/DamageType.h"
#include "GameFramework/Pawn.h"
#include "Kismet/GameplayStatics.h"
#include "TimerManager.h"

UHitscanWeaponComponent::UHitscanWeaponComponent()
{
	PrimaryComponentTick.bCanEverTick = false;
	DamageTypeClass = UDamageType::StaticClass();
}

void UHitscanWeaponComponent::StartFire()
{
	UWorld* World = GetWorld();
	if (!World || World->GetTimerManager().IsTimerActive(FireTimerHandle))
	{
		return;
	}
	const float Interval = 60.f / RoundsPerMinute;
	const double Now = World->GetTimeSeconds();
	const float FirstDelay = FMath::Max(0.f, static_cast<float>(LastFireTime + Interval - Now));
	if (FirstDelay <= 0.f)
	{
		FireShot();
		World->GetTimerManager().SetTimer(FireTimerHandle, this, &UHitscanWeaponComponent::FireShot, Interval, true);
	}
	else
	{
		World->GetTimerManager().SetTimer(FireTimerHandle, this, &UHitscanWeaponComponent::FireShot, Interval, true, FirstDelay);
	}
}

void UHitscanWeaponComponent::StopFire()
{
	if (UWorld* World = GetWorld())
	{
		World->GetTimerManager().ClearTimer(FireTimerHandle);
	}
}

void UHitscanWeaponComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
	StopFire();
	Super::EndPlay(EndPlayReason);
}

void UHitscanWeaponComponent::FireShot()
{
	AActor* Owner = GetOwner();
	UWorld* World = GetWorld();
	if (!Owner || !World)
	{
		return;
	}
	LastFireTime = World->GetTimeSeconds();

	FVector EyeLocation;
	FRotator EyeRotation;
	Owner->GetActorEyesViewPoint(EyeLocation, EyeRotation);

	const FVector Direction = FMath::VRandCone(EyeRotation.Vector(), FMath::DegreesToRadians(SpreadDegrees));
	const FVector TraceEnd = EyeLocation + Direction * Range;

	FCollisionQueryParams Params(SCENE_QUERY_STAT(HitscanWeapon), /*bTraceComplex=*/ true);
	Params.AddIgnoredActor(Owner);
	Params.bReturnPhysicalMaterial = true;

	FHitResult Hit;
	if (World->LineTraceSingleByChannel(Hit, EyeLocation, TraceEnd, ECC_Visibility, Params))
	{
		if (AActor* HitActor = Hit.GetActor())
		{
			const APawn* OwnerPawn = Cast<APawn>(Owner);
			AController* InstigatorController = OwnerPawn ? OwnerPawn->GetController() : nullptr;
			UGameplayStatics::ApplyPointDamage(HitActor, Damage, Direction, Hit, InstigatorController, Owner, DamageTypeClass);
		}
	}
}

