#include "ProgressSaveSubsystem.h"
#include "ProgressSaveGame.h"
#include "Kismet/GameplayStatics.h"

const FString UProgressSaveSubsystem::SlotName = TEXT("Main");

void UProgressSaveSubsystem::Initialize(FSubsystemCollectionBase& Collection)
{
	Super::Initialize(Collection);

	if (UGameplayStatics::DoesSaveGameExist(SlotName, UserIndex))
	{
		CurrentSave = Cast<UProgressSaveGame>(UGameplayStatics::LoadGameFromSlot(SlotName, UserIndex));
	}
	if (!CurrentSave)
	{
		CurrentSave = Cast<UProgressSaveGame>(UGameplayStatics::CreateSaveGameObject(UProgressSaveGame::StaticClass()));
	}
}

void UProgressSaveSubsystem::Deinitialize()
{
	CurrentSave = nullptr;
	Super::Deinitialize();
}

void UProgressSaveSubsystem::SaveNow()
{
	if (!CurrentSave || bSaveInFlight)
	{
		return;
	}
	bSaveInFlight = true;
	FAsyncSaveGameToSlotDelegate Done;
	Done.BindUObject(this, &UProgressSaveSubsystem::HandleSaveFinished);
	UGameplayStatics::AsyncSaveGameToSlot(CurrentSave, SlotName, UserIndex, Done);
}

void UProgressSaveSubsystem::HandleSaveFinished(const FString& InSlotName, const int32 InUserIndex, bool bSuccess)
{
	bSaveInFlight = false;
	OnSaveCompleted.Broadcast(bSuccess);
}

