AWeaponPickup::AWeaponPickup()
{
	PrimaryActorTick.bCanEverTick = false;
	MeshComponent = CreateDefaultSubobject<USkeletalMeshComponent>(TEXT("Mesh"));
	RootComponent = MeshComponent;
}

void AWeaponPickup::BeginPlay()
{
	Super::BeginPlay();
	RequestAssets();
}

void AWeaponPickup::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
	if (LoadHandle.IsValid())
	{
		LoadHandle->CancelHandle();
		LoadHandle.Reset();
	}
	Super::EndPlay(EndPlayReason);
}

void AWeaponPickup::SetWeaponData(UWeaponData* NewData)
{
	WeaponData = NewData;
	RequestAssets();
}

void AWeaponPickup::RequestAssets()
{
	if (LoadHandle.IsValid())
	{
		LoadHandle->CancelHandle();
		LoadHandle.Reset();
	}
	if (!WeaponData)
	{
		return;
	}

	TArray<FSoftObjectPath> Paths;
	if (!WeaponData->Mesh.IsNull())
	{
		Paths.Add(WeaponData->Mesh.ToSoftObjectPath());
	}
	if (!WeaponData->FireSound.IsNull())
	{
		Paths.Add(WeaponData->FireSound.ToSoftObjectPath());
	}
	if (Paths.Num() == 0)
	{
		return;
	}

	FStreamableManager& Streamable = UAssetManager::GetStreamableManager();
	LoadHandle = Streamable.RequestAsyncLoad(Paths, FStreamableDelegate::CreateUObject(this, &AWeaponPickup::OnAssetsLoaded));
}

void AWeaponPickup::OnAssetsLoaded()
{
	if (!WeaponData)
	{
		return;
	}
	if (USkeletalMesh* LoadedMesh = WeaponData->Mesh.Get())
	{
		MeshComponent->SetSkeletalMeshAsset(LoadedMesh);
	}
	LoadedFireSound = WeaponData->FireSound.Get();
	LoadHandle.Reset();
}

