// File: InventoryComponent.cpp
#include "InventoryComponent.h"
#include "GameFramework/Actor.h"
#include "Net/UnrealNetwork.h"

UInventoryComponent::UInventoryComponent()
{
	PrimaryComponentTick.bCanEverTick = false;
	SetIsReplicatedByDefault(true);
}

void UInventoryComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
	Super::GetLifetimeReplicatedProps(OutLifetimeProps);
	DOREPLIFETIME(UInventoryComponent, Entries);
}

bool UInventoryComponent::IsAuthority() const
{
	const AActor* Owner = GetOwner();
	return Owner && Owner->HasAuthority();
}

int32 UInventoryComponent::FindIndex(FName ItemId) const
{
	return Entries.IndexOfByPredicate([ItemId](const FInventoryEntry& Entry) { return Entry.ItemId == ItemId; });
}

int32 UInventoryComponent::GetCount(FName ItemId) const
{
	const int32 Index = FindIndex(ItemId);
	return Index == INDEX_NONE ? 0 : Entries[Index].Count;
}

int32 UInventoryComponent::AddItem(FName ItemId, int32 Amount)
{
	if (!IsAuthority() || ItemId.IsNone() || Amount <= 0)
	{
		return GetCount(ItemId);
	}
	int32 Index = FindIndex(ItemId);
	if (Index == INDEX_NONE)
	{
		FInventoryEntry NewEntry;
		NewEntry.ItemId = ItemId;
		Index = Entries.Add(NewEntry);
	}
	Entries[Index].Count += Amount;
	const int32 NewCount = Entries[Index].Count;
	OnItemCountChanged.Broadcast(ItemId, NewCount);
	OnInventoryUpdated.Broadcast();
	return NewCount;
}

bool UInventoryComponent::RemoveItem(FName ItemId, int32 Amount)
{
	const int32 Index = FindIndex(ItemId);
	if (!IsAuthority() || Amount <= 0 || Index == INDEX_NONE || Entries[Index].Count < Amount)
	{
		return false;
	}
	Entries[Index].Count -= Amount;
	const int32 NewCount = Entries[Index].Count;
	if (NewCount == 0)
	{
		Entries.RemoveAt(Index);
	}
	OnItemCountChanged.Broadcast(ItemId, NewCount);
	OnInventoryUpdated.Broadcast();
	return true;
}

void UInventoryComponent::ServerUseItem_Implementation(FName ItemId)
{
	RemoveItem(ItemId, 1);
}

void UInventoryComponent::OnRep_Entries()
{
	OnInventoryUpdated.Broadcast();
}

