// File: ProceduralTerrain.cpp
#include "ProceduralTerrain.h"
#include "Async/Async.h"
#include "Async/ParallelFor.h"
#include "Math/RandomStream.h"

AProceduralTerrain::AProceduralTerrain()
{
	PrimaryActorTick.bCanEverTick = false;
}

void AProceduralTerrain::Generate(int32 Seed)
{
	const int32 RequestId = ++LatestRequestId;
	State = ETerrainState::Generating;

	// Copy everything the worker needs: it must not touch this UObject.
	const int32 GridSize = Size;
	const float Scale = NoiseScale;
	const float Amplitude = HeightScale;
	TWeakObjectPtr<AProceduralTerrain> WeakThis(this);

	Async(EAsyncExecution::ThreadPool, [WeakThis, RequestId, GridSize, Scale, Amplitude, Seed]()
	{
		FRandomStream Stream(Seed);
		const FVector2D Offset(Stream.FRandRange(-10000.f, 10000.f), Stream.FRandRange(-10000.f, 10000.f));

		TArray<float> Result;
		Result.SetNumUninitialized(GridSize * GridSize);
		ParallelFor(GridSize, [&Result, GridSize, Scale, Amplitude, Offset](int32 Y)
		{
			for (int32 X = 0; X < GridSize; ++X)
			{
				const FVector2D P(X * Scale + Offset.X, Y * Scale + Offset.Y);
				Result[Y * GridSize + X] = FMath::PerlinNoise2D(P) * Amplitude;
			}
		});

		AsyncTask(ENamedThreads::GameThread, [WeakThis, RequestId, Result = MoveTemp(Result)]() mutable
		{
			if (AProceduralTerrain* Self = WeakThis.Get())
			{
				Self->ApplyHeights(RequestId, MoveTemp(Result));
			}
		});
	});
}

void AProceduralTerrain::ApplyHeights(int32 RequestId, TArray<float>&& NewHeights)
{
	check(IsInGameThread());
	if (RequestId != LatestRequestId)
	{
		return; // a newer Generate() call superseded this result
	}
	Heights = MoveTemp(NewHeights);
	HeightsSize = FMath::RoundToInt(FMath::Sqrt(static_cast<float>(Heights.Num())));
	State = ETerrainState::Ready;
	OnTerrainReady.Broadcast();
}

float AProceduralTerrain::GetHeightAt(int32 X, int32 Y) const
{
	if (State != ETerrainState::Ready || X < 0 || Y < 0 || X >= HeightsSize || Y >= HeightsSize)
	{
		return 0.f;
	}
	return Heights[Y * HeightsSize + X];
}
